from collections import Counter

def analyze_grid_colors(grid):
    """Count components for each color in grid"""
    h, w = len(grid), len(grid[0])
    result = {}

    for color in set(val for row in grid for val in row):
        # Find all components
        visited = set()
        components = []
        for i in range(h):
            for j in range(w):
                if grid[i][j] == color and (i, j) not in visited:
                    # BFS to find component
                    comp_cells = []
                    queue = [(i, j)]
                    visited.add((i, j))
                    while queue:
                        ci, cj = queue.pop(0)
                        comp_cells.append((ci, cj))
                        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                            ni, nj = ci+di, cj+dj
                            if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == color and (ni, nj) not in visited:
                                visited.add((ni, nj))
                                queue.append((ni, nj))
                    components.append(len(comp_cells))
        result[color] = {
            'count': sum(components),
            'n_components': len(components),
            'max_comp_size': max(components) if components else 0
        }
    return result

